create extension if not exists pgmq;
create schema bug_ops;
revoke all on schema bug_ops from public, anon, authenticated, service_role, authenticator;
grant usage on schema bug_ops to postgres;
do $$ declare q text; begin foreach q in array array['bug_work_mune','bug_work_masa','bug_work_voss','bug_work_one'] loop if not exists(select 1 from pgmq.meta where queue_name=q) then perform pgmq.create(q); end if; end loop; end $$;
create table bug_ops.system_config(singleton boolean primary key default true check(singleton),project_key text not null check(project_key in ('VERA','BT2')),project_ref text not null unique,coordinator_role text not null check(coordinator_role in ('MUNE','MASA','VOSS','ONE')));
insert into bug_ops.system_config(singleton,project_key,project_ref,coordinator_role) values(true,'VERA','klmbpaigzeguvnpccqzz','VOSS');
create table bug_ops.bug_reports(bug_id uuid primary key default gen_random_uuid(),home_project text not null check(home_project in ('VERA','BT2')),intake_key text not null unique check(length(btrim(intake_key)) between 1 and 200),intake_digest text not null check(intake_digest ~ '^[0-9a-f]{64}$'),title text not null check(length(btrim(title)) between 1 and 300),description text not null default '',severity text not null check(severity in ('LOW','MEDIUM','HIGH','CRITICAL')),status text not null check(status in ('NEW','TRIAGED','IN_PROGRESS','BLOCKED','FIXED','VERIFYING','CLOSED','REOPENED')),component text,reported_by text,assigned_role text not null check(assigned_role in ('MUNE','MASA','VOSS','ONE')),state_version bigint not null check(state_version>=1),routing_revision bigint not null check(routing_revision>=1),evidence jsonb not null default '{}'::jsonb check(jsonb_typeof(evidence)='object'),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),closed_at timestamptz,check((status='CLOSED' and closed_at is not null) or (status<>'CLOSED' and closed_at is null)));
create index bug_reports_open_role_idx on bug_ops.bug_reports(assigned_role,status,state_version) where status<>'CLOSED';
create table bug_ops.bug_events(event_id uuid primary key default gen_random_uuid(),bug_id uuid not null references bug_ops.bug_reports(bug_id),state_version bigint not null check(state_version>=1),routing_revision bigint not null check(routing_revision>=1),event_type text not null check(event_type in ('REPORTED','ROUTED','STATUS_CHANGED','REOPENED')),actor text,operation_id uuid not null unique,request_digest text not null check(request_digest ~ '^[0-9a-f]{64}$'),request_payload jsonb not null check(jsonb_typeof(request_payload)='object'),details jsonb not null default '{}'::jsonb check(jsonb_typeof(details)='object'),dispatch_queue text,dispatch_msg_id bigint,created_at timestamptz not null default clock_timestamp(),unique(bug_id,state_version),check((dispatch_queue is null and dispatch_msg_id is null) or (dispatch_queue is not null and dispatch_msg_id is not null)));
create unique index bug_events_dispatch_idx on bug_ops.bug_events(dispatch_queue,dispatch_msg_id) where dispatch_msg_id is not null;
create index bug_events_bug_idx on bug_ops.bug_events(bug_id,created_at);
create table bug_ops.dispatch_events(dispatch_event_id uuid primary key default gen_random_uuid(),queue_name text not null,msg_id bigint not null,classification text not null check(classification in ('HANDLED','STALE','POISON','CLOSED','WRONG_TARGET')),bug_id uuid,source_event_id uuid,handled_event_id uuid,observed_message jsonb not null,note text,created_at timestamptz not null default clock_timestamp(),unique(queue_name,msg_id));
create function bug_ops.block_immutable_mutation() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'BUG_OPS_IMMUTABLE_RELATION'; end $$;
create trigger bug_events_immutable before update or delete on bug_ops.bug_events for each row execute function bug_ops.block_immutable_mutation();
create trigger dispatch_events_immutable before update or delete on bug_ops.dispatch_events for each row execute function bug_ops.block_immutable_mutation();
create function bug_ops.sha256_jsonb(p_value jsonb) returns text language sql immutable set search_path='' as $$ select encode(extensions.digest(convert_to(p_value::text,'UTF8'),'sha256'),'hex') $$;
create function bug_ops.queue_for_role(p_role text) returns text language plpgsql immutable set search_path='' as $$ declare r text:=upper(btrim(p_role)); begin return case r when 'MUNE' then 'bug_work_mune' when 'MASA' then 'bug_work_masa' when 'VOSS' then 'bug_work_voss' when 'ONE' then 'bug_work_one' else null end; end $$;
create function bug_ops.report_bug(p_operation_id uuid,p_intake_key text,p_title text,p_description text default '',p_severity text default 'MEDIUM',p_component text default null,p_reported_by text default null,p_assigned_role text default null,p_evidence jsonb default '{}'::jsonb) returns table(out_bug_id uuid,out_event_id uuid,out_state_version bigint,out_routing_revision bigint,out_queue_name text,out_queue_msg_id bigint,idempotent_replay boolean) language plpgsql set search_path='' as $$ declare cfg bug_ops.system_config%rowtype; v_role text; v_queue text; v_payload jsonb; v_digest text; ev bug_ops.bug_events%rowtype; br bug_ops.bug_reports%rowtype; v_bug uuid:=gen_random_uuid(); v_event uuid:=gen_random_uuid(); v_msg bigint; v_sev text:=upper(btrim(p_severity)); v_key text:=btrim(p_intake_key); v_title text:=btrim(p_title); begin select * into cfg from bug_ops.system_config where singleton=true; v_role:=coalesce(upper(nullif(btrim(p_assigned_role),'')),cfg.coordinator_role); v_queue:=bug_ops.queue_for_role(v_role); if v_queue is null then raise exception 'INVALID_TARGET_ROLE'; end if; if v_key is null or length(v_key)=0 then raise exception 'INVALID_INTAKE_KEY'; end if; if v_title is null or length(v_title)=0 then raise exception 'INVALID_TITLE'; end if; if v_sev not in ('LOW','MEDIUM','HIGH','CRITICAL') then raise exception 'INVALID_SEVERITY'; end if; if jsonb_typeof(coalesce(p_evidence,'{}'::jsonb))<>'object' then raise exception 'INVALID_EVIDENCE'; end if; v_payload:=jsonb_build_object('kind','REPORT','home_project',cfg.project_key,'intake_key',v_key,'title',v_title,'description',coalesce(p_description,''),'severity',v_sev,'component',p_component,'reported_by',p_reported_by,'assigned_role',v_role,'evidence',coalesce(p_evidence,'{}'::jsonb)); v_digest:=bug_ops.sha256_jsonb(v_payload); select * into ev from bug_ops.bug_events e where e.operation_id=p_operation_id; if found then if ev.request_digest<>v_digest then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if; return query select ev.bug_id,ev.event_id,ev.state_version,ev.routing_revision,ev.dispatch_queue,ev.dispatch_msg_id,true; return; end if; select * into br from bug_ops.bug_reports b where b.intake_key=v_key; if found then if br.intake_digest<>v_digest then raise exception 'INTAKE_KEY_REUSE_CONFLICT'; end if; select * into ev from bug_ops.bug_events e where e.bug_id=br.bug_id and e.event_type='REPORTED' order by e.state_version limit 1; return query select br.bug_id,ev.event_id,br.state_version,br.routing_revision,ev.dispatch_queue,null::bigint,true; return; end if; select s into v_msg from pgmq.send(v_queue,jsonb_build_object('bug_id',v_bug,'home_project',cfg.project_key,'event_id',v_event,'state_version',1,'routing_revision',1,'target_role',v_role,'action','BUG_REPORTED','operation_id',p_operation_id),0) s limit 1; insert into bug_ops.bug_reports(bug_id,home_project,intake_key,intake_digest,title,description,severity,status,component,reported_by,assigned_role,state_version,routing_revision,evidence) values(v_bug,cfg.project_key,v_key,v_digest,v_title,coalesce(p_description,''),v_sev,'NEW',p_component,p_reported_by,v_role,1,1,coalesce(p_evidence,'{}'::jsonb)); insert into bug_ops.bug_events(event_id,bug_id,state_version,routing_revision,event_type,actor,operation_id,request_digest,request_payload,details,dispatch_queue,dispatch_msg_id) values(v_event,v_bug,1,1,'REPORTED',p_reported_by,p_operation_id,v_digest,v_payload,jsonb_build_object('assigned_role',v_role),v_queue,v_msg); return query select v_bug,v_event,1::bigint,1::bigint,v_queue,v_msg,false; end $$;
create function bug_ops.route_bug(p_operation_id uuid,p_bug_id uuid,p_expected_state_version bigint,p_expected_routing_revision bigint,p_target_role text,p_actor text default null,p_reason text default null) returns table(out_bug_id uuid,out_event_id uuid,out_state_version bigint,out_routing_revision bigint,out_queue_name text,out_queue_msg_id bigint,idempotent_replay boolean) language plpgsql set search_path='' as $$ declare br bug_ops.bug_reports%rowtype; ev bug_ops.bug_events%rowtype; cfg bug_ops.system_config%rowtype; v_role text:=upper(btrim(p_target_role)); v_queue text; v_payload jsonb; v_digest text; v_event uuid:=gen_random_uuid(); v_msg bigint; v_state bigint; v_route bigint; begin select * into cfg from bug_ops.system_config where singleton=true; v_queue:=bug_ops.queue_for_role(v_role); if v_queue is null then raise exception 'INVALID_TARGET_ROLE'; end if; v_payload:=jsonb_build_object('kind','ROUTE','home_project',cfg.project_key,'bug_id',p_bug_id,'expected_state_version',p_expected_state_version,'expected_routing_revision',p_expected_routing_revision,'target_role',v_role,'actor',p_actor,'reason',p_reason); v_digest:=bug_ops.sha256_jsonb(v_payload); select * into ev from bug_ops.bug_events e where e.operation_id=p_operation_id; if found then if ev.request_digest<>v_digest then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if; return query select ev.bug_id,ev.event_id,ev.state_version,ev.routing_revision,ev.dispatch_queue,ev.dispatch_msg_id,true; return; end if; select * into br from bug_ops.bug_reports b where b.bug_id=p_bug_id for update; if not found then raise exception 'BUG_NOT_FOUND'; end if; if br.state_version<>p_expected_state_version then raise exception 'STALE_STATE_VERSION expected %, actual %',p_expected_state_version,br.state_version; end if; if br.routing_revision<>p_expected_routing_revision then raise exception 'STALE_ROUTING_REVISION expected %, actual %',p_expected_routing_revision,br.routing_revision; end if; if br.status='CLOSED' then raise exception 'BUG_CLOSED'; end if; v_state:=br.state_version+1; v_route:=br.routing_revision+1; select s into v_msg from pgmq.send(v_queue,jsonb_build_object('bug_id',p_bug_id,'home_project',br.home_project,'event_id',v_event,'state_version',v_state,'routing_revision',v_route,'target_role',v_role,'action','ROUTE','operation_id',p_operation_id),0) s limit 1; update bug_ops.bug_reports set assigned_role=v_role,state_version=v_state,routing_revision=v_route,updated_at=clock_timestamp() where bug_id=p_bug_id; insert into bug_ops.bug_events(event_id,bug_id,state_version,routing_revision,event_type,actor,operation_id,request_digest,request_payload,details,dispatch_queue,dispatch_msg_id) values(v_event,p_bug_id,v_state,v_route,'ROUTED',p_actor,p_operation_id,v_digest,v_payload,jsonb_build_object('from_role',br.assigned_role,'to_role',v_role,'reason',p_reason),v_queue,v_msg); return query select p_bug_id,v_event,v_state,v_route,v_queue,v_msg,false; end $$;
create function bug_ops.update_bug_status(p_operation_id uuid,p_bug_id uuid,p_expected_state_version bigint,p_status text,p_actor text default null,p_note text default null) returns table(out_bug_id uuid,out_event_id uuid,out_state_version bigint,out_routing_revision bigint,idempotent_replay boolean) language plpgsql set search_path='' as $$ declare br bug_ops.bug_reports%rowtype; ev bug_ops.bug_events%rowtype; cfg bug_ops.system_config%rowtype; v_status text:=upper(btrim(p_status)); v_payload jsonb; v_digest text; v_event uuid:=gen_random_uuid(); v_state bigint; v_type text; begin select * into cfg from bug_ops.system_config where singleton=true; v_payload:=jsonb_build_object('kind','STATUS','home_project',cfg.project_key,'bug_id',p_bug_id,'expected_state_version',p_expected_state_version,'status',v_status,'actor',p_actor,'note',p_note); v_digest:=bug_ops.sha256_jsonb(v_payload); select * into ev from bug_ops.bug_events e where e.operation_id=p_operation_id; if found then if ev.request_digest<>v_digest then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if; return query select ev.bug_id,ev.event_id,ev.state_version,ev.routing_revision,true; return; end if; if v_status not in ('NEW','TRIAGED','IN_PROGRESS','BLOCKED','FIXED','VERIFYING','CLOSED','REOPENED') then raise exception 'INVALID_STATUS'; end if; select * into br from bug_ops.bug_reports b where b.bug_id=p_bug_id for update; if not found then raise exception 'BUG_NOT_FOUND'; end if; if br.state_version<>p_expected_state_version then raise exception 'STALE_STATE_VERSION expected %, actual %',p_expected_state_version,br.state_version; end if; if br.status='CLOSED' and v_status<>'REOPENED' then raise exception 'BUG_CLOSED_REQUIRES_REOPEN'; end if; v_state:=br.state_version+1; v_type:=case when v_status='REOPENED' then 'REOPENED' else 'STATUS_CHANGED' end; update bug_ops.bug_reports set status=v_status,state_version=v_state,updated_at=clock_timestamp(),closed_at=case when v_status='CLOSED' then clock_timestamp() else null end where bug_id=p_bug_id; insert into bug_ops.bug_events(event_id,bug_id,state_version,routing_revision,event_type,actor,operation_id,request_digest,request_payload,details) values(v_event,p_bug_id,v_state,br.routing_revision,v_type,p_actor,p_operation_id,v_digest,v_payload,jsonb_build_object('from_status',br.status,'to_status',v_status,'note',p_note)); return query select p_bug_id,v_event,v_state,br.routing_revision,false; end $$;
create function bug_ops.archive_dispatch_internal(p_queue text,p_msg_id bigint,p_classification text,p_message jsonb,p_bug_id uuid,p_source_event_id uuid,p_handled_event_id uuid,p_note text) returns uuid language plpgsql set search_path='' as $$ declare d bug_ops.dispatch_events%rowtype; v_id uuid:=gen_random_uuid(); ok boolean; begin select * into d from bug_ops.dispatch_events x where x.queue_name=p_queue and x.msg_id=p_msg_id; if found then if d.classification<>p_classification then raise exception 'DISPATCH_EVENT_CONFLICT'; end if; return d.dispatch_event_id; end if; select pgmq.archive(p_queue,p_msg_id) into ok; if not coalesce(ok,false) then raise exception 'QUEUE_MESSAGE_NOT_ACTIVE'; end if; insert into bug_ops.dispatch_events(dispatch_event_id,queue_name,msg_id,classification,bug_id,source_event_id,handled_event_id,observed_message,note) values(v_id,p_queue,p_msg_id,p_classification,p_bug_id,p_source_event_id,p_handled_event_id,coalesce(p_message,'null'::jsonb),p_note); return v_id; end $$;
create function bug_ops.claim_work(p_role text,p_visibility_seconds integer default 300,p_qty integer default 10) returns table(msg_id bigint,read_ct integer,enqueued_at timestamptz,vt timestamptz,message jsonb,headers jsonb,bug_id uuid,state_version bigint,routing_revision bigint,target_role text) language plpgsql set search_path='' as $$ declare v_role text:=upper(btrim(p_role)); v_queue text; cfg bug_ops.system_config%rowtype; r pgmq.message_record; br bug_ops.bug_reports%rowtype; ev bug_ops.bug_events%rowtype; v_bug uuid; v_event uuid; v_state bigint; v_route bigint; v_target text; v_home text; begin v_queue:=bug_ops.queue_for_role(v_role); if v_queue is null then raise exception 'INVALID_ROLE'; end if; if p_visibility_seconds<1 or p_visibility_seconds>86400 then raise exception 'INVALID_VISIBILITY'; end if; if p_qty<1 or p_qty>20 then raise exception 'INVALID_QTY'; end if; select * into cfg from bug_ops.system_config where singleton=true; for r in select * from pgmq.read(v_queue,p_visibility_seconds,p_qty,'{}'::jsonb) loop v_bug:=null; v_event:=null; v_state:=null; v_route:=null; v_target:=null; v_home:=null; begin if jsonb_typeof(r.message)<>'object' or not (r.message ?& array['bug_id','home_project','event_id','state_version','routing_revision','target_role','action','operation_id']) then raise exception 'MALFORMED'; end if; v_bug:=(r.message->>'bug_id')::uuid; v_event:=(r.message->>'event_id')::uuid; v_state:=(r.message->>'state_version')::bigint; v_route:=(r.message->>'routing_revision')::bigint; v_target:=upper(btrim(r.message->>'target_role')); v_home:=r.message->>'home_project'; exception when others then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'POISON',r.message,null,null,null,'malformed envelope'); continue; end; if v_home<>cfg.project_key then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'POISON',r.message,v_bug,v_event,null,'wrong home_project'); continue; end if; if v_target<>v_role then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'WRONG_TARGET',r.message,v_bug,v_event,null,'target does not match queue role'); continue; end if; select * into ev from bug_ops.bug_events e where e.event_id=v_event; if not found or ev.bug_id<>v_bug or ev.dispatch_queue is distinct from v_queue or ev.dispatch_msg_id is distinct from r.msg_id or ev.routing_revision<>v_route or ev.state_version<>v_state then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'POISON',r.message,v_bug,v_event,null,'event binding mismatch'); continue; end if; select * into br from bug_ops.bug_reports b where b.bug_id=v_bug; if not found then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'POISON',r.message,v_bug,v_event,null,'unknown bug'); continue; end if; if br.status='CLOSED' then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'CLOSED',r.message,v_bug,v_event,null,'bug closed'); continue; end if; if br.assigned_role<>v_role or br.routing_revision<>v_route then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'STALE',r.message,v_bug,v_event,null,'routing no longer current'); continue; end if; if v_state>br.state_version then perform bug_ops.archive_dispatch_internal(v_queue,r.msg_id,'POISON',r.message,v_bug,v_event,null,'future state version'); continue; end if; return query select r.msg_id,r.read_ct,r.enqueued_at,r.vt,r.message,r.headers,v_bug,br.state_version,br.routing_revision,v_role; end loop; end $$;
create function bug_ops.ack_work(p_role text,p_msg_id bigint,p_handled_event_id uuid,p_note text default null) returns uuid language plpgsql set search_path='' as $$ declare v_role text:=upper(btrim(p_role)); v_queue text; v_message jsonb; v_bug uuid; v_source uuid; src bug_ops.bug_events%rowtype; handled bug_ops.bug_events%rowtype; d bug_ops.dispatch_events%rowtype; begin v_queue:=bug_ops.queue_for_role(v_role); if v_queue is null then raise exception 'INVALID_ROLE'; end if; select * into d from bug_ops.dispatch_events x where x.queue_name=v_queue and x.msg_id=p_msg_id; if found then if d.classification='HANDLED' and d.handled_event_id=p_handled_event_id then return d.dispatch_event_id; else raise exception 'DISPATCH_ALREADY_FINALIZED'; end if; end if; execute format('select message from pgmq.%I where msg_id=$1','q_'||v_queue) into v_message using p_msg_id; if v_message is null then raise exception 'QUEUE_MESSAGE_NOT_ACTIVE'; end if; begin v_bug:=(v_message->>'bug_id')::uuid; v_source:=(v_message->>'event_id')::uuid; exception when others then raise exception 'ACK_MALFORMED_MESSAGE'; end; select * into src from bug_ops.bug_events e where e.event_id=v_source; if not found or src.bug_id<>v_bug or src.dispatch_queue is distinct from v_queue or src.dispatch_msg_id is distinct from p_msg_id then raise exception 'ACK_SOURCE_BINDING_MISMATCH'; end if; select * into handled from bug_ops.bug_events e where e.event_id=p_handled_event_id; if not found or handled.bug_id<>v_bug or handled.state_version<=src.state_version then raise exception 'ACK_REQUIRES_LATER_BUG_EVENT'; end if; return bug_ops.archive_dispatch_internal(v_queue,p_msg_id,'HANDLED',v_message,v_bug,v_source,p_handled_event_id,p_note); end $$;
revoke all on all tables in schema bug_ops from public,anon,authenticated,service_role,authenticator;
revoke all on all sequences in schema bug_ops from public,anon,authenticated,service_role,authenticator;
revoke execute on all functions in schema bug_ops from public,anon,authenticated,service_role,authenticator;
grant select,insert,update,delete on bug_ops.bug_reports to postgres;
grant select on bug_ops.bug_events,bug_ops.dispatch_events,bug_ops.system_config to postgres;
grant execute on all functions in schema bug_ops to postgres;
revoke all on schema pgmq from public,anon,authenticated,service_role,authenticator;
revoke execute on all functions in schema pgmq from public,anon,authenticated,service_role,authenticator;